function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPnfReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PnfReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PnfReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPnfReceipt(sttRec: string): Promise<PnfReceipt> {
  const res = await apiClient.get<BffResponse<PnfReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPnfReceipt(body: PnfReceiptWrite): Promise<PnfReceipt> {
  const res = await apiClient.post<BffResponse<PnfReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePnfReceipt(sttRec: string, body: PnfReceiptWrite): Promise<PnfReceipt> {
  const res = await apiClient.put<BffResponse<PnfReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
